#!/usr/bin/env python3
"""Remove executable JavaScript from an HTML file in place.

The sanitizer deliberately uses a deny-list for executable constructs rather
than an HTML allow-list: ordinary elements and attributes are retained unless
they can run script or navigate an executable URL.  Files that require no
changes are left byte-for-byte untouched.
"""

from __future__ import annotations

import codecs
import html
import re
import sys
import unicodedata
import urllib.parse
from pathlib import Path
from typing import Iterable

from bs4 import BeautifulSoup, Comment, ProcessingInstruction, UnicodeDammit
from bs4.dammit import EntitySubstitution
from bs4.formatter import HTMLFormatter


_SCRIPT_NAMES = {"script"}
_ACTIVE_SCHEMES = {"javascript", "vbscript", "livescript", "mocha"}
_RASTER_DATA_MIMES = {
    "image/avif",
    "image/bmp",
    "image/gif",
    "image/jpeg",
    "image/jpg",
    "image/png",
    "image/vnd.microsoft.icon",
    "image/webp",
    "image/x-icon",
}

# Attributes whose value is interpreted as one URL by HTML or SVG.
_URL_ATTRIBUTES = {
    "action",
    "archive",
    "background",
    "cite",
    "classid",
    "code",
    "codebase",
    "data",
    "dynsrc",
    "formaction",
    "href",
    "icon",
    "longdesc",
    "lowsrc",
    "manifest",
    "poster",
    "profile",
    "src",
    "usemap",
    "xlink:href",
    "xml:base",
}
_MULTI_URL_ATTRIBUTES = {"ping"}
_SRCSET_ATTRIBUTES = {"imagesrcset", "srcset"}

# SVG presentation attributes can contain CSS url(...) values.
_CSS_VALUE_ATTRIBUTES = {
    "clip-path",
    "color-profile",
    "cursor",
    "fill",
    "filter",
    "marker",
    "marker-end",
    "marker-mid",
    "marker-start",
    "mask",
    "stroke",
}

_ANIMATION_TAGS = {"animate", "animatemotion", "animatetransform", "set"}
_ANIMATED_URL_ATTRIBUTES = _URL_ATTRIBUTES | _CSS_VALUE_ATTRIBUTES | {
    "srcdoc",
    "style",
}

_CSS_COMMENT_RE = re.compile(r"/\*.*?\*/", re.DOTALL)
_CSS_ESCAPE_RE = re.compile(
    r"\\(?:([0-9a-fA-F]{1,6})(?:[ \t\r\n\f])?|([^\r\n\f]))",
    re.DOTALL,
)
_URL_FUNCTION_RE = re.compile(r"url\s*\(\s*(.*?)\s*\)", re.IGNORECASE | re.DOTALL)
_IMPORT_RE = re.compile(
    r"@import\s+(?:url\s*\(\s*)?(['\"]?)(.*?)\1\s*\)?(?:\s|;|$)",
    re.IGNORECASE | re.DOTALL,
)


class _PreserveAttributeOrderFormatter(HTMLFormatter):
    """Keep parser attribute order instead of Beautiful Soup's sorting."""

    def attributes(self, tag):  # type: ignore[override]
        yield from tag.attrs.items()


_FORMATTER = _PreserveAttributeOrderFormatter(
    entity_substitution=EntitySubstitution.substitute_xml
)


def _local_name(name: object) -> str:
    """Return a lower-case local name for ordinary and namespaced names."""

    return str(name).lower().rsplit(":", 1)[-1]


def _attribute_text(value: object) -> str:
    if value is None:
        return ""
    if isinstance(value, (list, tuple)):
        return " ".join(str(part) for part in value)
    return str(value)


def _decode_obfuscation(value: str) -> str:
    """Decode entity and percent encodings commonly used to hide URL schemes."""

    result = value
    for _ in range(6):
        decoded = html.unescape(result)
        try:
            decoded = urllib.parse.unquote(decoded, errors="replace")
        except (TypeError, ValueError):
            pass
        if decoded == result:
            break
        result = decoded
    return result


def _compact_scheme_text(value: str) -> str:
    value = _decode_obfuscation(value)
    # Browsers ignore leading ASCII controls/whitespace around URLs.  Removing
    # all such characters also catches java\nscript and zero-width obfuscation.
    return "".join(
        character
        for character in value
        if not character.isspace()
        and ord(character) > 0x20
        and ord(character) != 0x7F
        and unicodedata.category(character) not in {"Cc", "Cf"}
    ).lower()


def _is_dangerous_url(value: str, *, allow_raster_data: bool = False) -> bool:
    compact = _compact_scheme_text(value).lstrip("\ufeff")
    match = re.match(r"^([a-z][a-z0-9+.-]*):", compact)
    if not match:
        return False

    scheme = match.group(1)
    if scheme in _ACTIVE_SCHEMES:
        return True

    if scheme in {"blob", "filesystem"}:
        # These can reference attacker-created active documents and cannot be
        # validated from a static HTML file.
        return True

    if scheme != "data":
        return False

    if not allow_raster_data:
        return True

    metadata = compact[5:].split(",", 1)[0]
    media_type = metadata.split(";", 1)[0] or "text/plain"
    return media_type not in _RASTER_DATA_MIMES


def _css_unescape(value: str) -> str:
    def replace_escape(match: re.Match[str]) -> str:
        hexadecimal, escaped = match.groups()
        if hexadecimal is not None:
            try:
                codepoint = int(hexadecimal, 16)
                if codepoint == 0 or codepoint > 0x10FFFF:
                    return "\ufffd"
                return chr(codepoint)
            except ValueError:
                return "\ufffd"
        return escaped or ""

    result = value
    for _ in range(4):
        decoded = _CSS_COMMENT_RE.sub("", result)
        decoded = _CSS_ESCAPE_RE.sub(replace_escape, decoded)
        decoded = _decode_obfuscation(decoded)
        if decoded == result:
            break
        result = decoded
    return result


def _css_is_dangerous(css: str) -> bool:
    decoded = _css_unescape(css)
    compact = "".join(
        character
        for character in decoded.lower()
        if not character.isspace()
        and ord(character) > 0x20
        and ord(character) != 0x7F
        and unicodedata.category(character) not in {"Cc", "Cf"}
    )

    # Legacy browser script features and executable bindings.
    if "expression(" in compact:
        return True
    if re.search(r"(?:^|[;{])(?:-moz-binding|behavior|behaviour):", compact):
        return True

    # Catch active schemes even when stored in a custom property and used via
    # var(), as well as old browser syntax that did not require url(...).
    if any(f"{scheme}:" in compact for scheme in _ACTIVE_SCHEMES):
        return True

    for match in _URL_FUNCTION_RE.finditer(decoded):
        candidate = match.group(1).strip().strip("'\"")
        if _is_dangerous_url(candidate, allow_raster_data=True):
            return True

    for match in _IMPORT_RE.finditer(decoded):
        candidate = match.group(2).strip().strip("'\"")
        if _is_dangerous_url(candidate, allow_raster_data=False):
            return True

    return False


def _split_css_declarations(css: str) -> Iterable[str]:
    """Split a style attribute at top-level semicolons, retaining formatting."""

    start = 0
    quote: str | None = None
    escaped = False
    comment = False
    parentheses = 0
    index = 0

    while index < len(css):
        pair = css[index : index + 2]
        character = css[index]

        if comment:
            if pair == "*/":
                comment = False
                index += 2
                continue
            index += 1
            continue

        if quote is not None:
            if escaped:
                escaped = False
            elif character == "\\":
                escaped = True
            elif character == quote:
                quote = None
            index += 1
            continue

        if pair == "/*":
            comment = True
            index += 2
            continue
        if character in {"'", '"'}:
            quote = character
        elif character == "(":
            parentheses += 1
        elif character == ")" and parentheses:
            parentheses -= 1
        elif character == ";" and parentheses == 0:
            yield css[start : index + 1]
            start = index + 1
        index += 1

    if start < len(css):
        yield css[start:]


def _sanitize_style_attribute(css: str) -> tuple[str, bool]:
    if not _css_is_dangerous(css):
        return css, False

    kept: list[str] = []
    changed = False
    for declaration in _split_css_declarations(css):
        if _css_is_dangerous(declaration):
            changed = True
        else:
            kept.append(declaration)

    result = "".join(kept)
    # If a payload crossed declaration boundaries or the input was malformed,
    # fail closed instead of returning CSS our splitter did not understand.
    if _css_is_dangerous(result):
        return "", True
    return result, changed


def _srcset_is_dangerous(value: str) -> bool:
    # A practical srcset parser: commas delimit candidates except for the first
    # comma in a data URL.  Data URLs are checked separately and only raster
    # image media types are allowed.
    decoded = _decode_obfuscation(value)
    position = 0
    length = len(decoded)

    while position < length:
        while position < length and (decoded[position].isspace() or decoded[position] == ","):
            position += 1
        if position >= length:
            break

        start = position
        is_data = decoded[position : position + 5].lower() == "data:"
        if is_data:
            comma = decoded.find(",", position)
            if comma == -1:
                candidate = decoded[position:]
                position = length
            else:
                # Consume the data payload up to whitespace; a following comma
                # begins another candidate.
                position = comma + 1
                while position < length and not decoded[position].isspace():
                    position += 1
                candidate = decoded[start:position]
        else:
            while position < length and not decoded[position].isspace() and decoded[position] != ",":
                position += 1
            candidate = decoded[start:position]

        if _is_dangerous_url(candidate, allow_raster_data=True):
            return True

        # Skip descriptors to the next candidate comma.
        while position < length and decoded[position] != ",":
            position += 1

    return False


def _meta_refresh_is_dangerous(content: str) -> bool:
    decoded = _decode_obfuscation(content)
    if ";" not in decoded:
        return False
    candidate = decoded.split(";", 1)[1].strip()
    if candidate.lower().startswith("url"):
        candidate = candidate[3:].lstrip()
        if candidate.startswith("="):
            candidate = candidate[1:].lstrip()
    return _is_dangerous_url(candidate.strip().strip("'\""))


def _conditional_comment(value: str) -> bool:
    lowered = value.lstrip().lower()
    return lowered.startswith("[if") or lowered.startswith("<![endif")


def _sanitize_once(markup: str, *, depth: int) -> tuple[str, bool]:
    soup = BeautifulSoup(markup, "html.parser")
    changed = False

    # Remove script elements first so their descendants cannot influence later
    # processing.  Local-name matching also catches namespaced script elements.
    for tag in list(soup.find_all(True)):
        if tag.name is not None and _local_name(tag.name) in _SCRIPT_NAMES:
            tag.decompose()
            changed = True

    # Conditional comments were executable HTML in older versions of IE.
    for node in list(soup.find_all(string=lambda text: isinstance(text, Comment))):
        if _conditional_comment(str(node)):
            node.extract()
            changed = True

    # Dangerous XML processing instructions can attach an active stylesheet.
    for node in list(
        soup.find_all(string=lambda text: isinstance(text, ProcessingInstruction))
    ):
        instruction = str(node)
        if _css_is_dangerous(instruction) or "xml-stylesheet" in instruction.lower():
            node.extract()
            changed = True

    for tag in list(soup.find_all(True)):
        if tag.name is None or tag.attrs is None:
            continue
        tag_name = _local_name(tag.name)

        # Obsolete HTML imports can load documents containing script.
        if tag_name == "link":
            rel = {_local_name(item) for item in _attribute_text(tag.get("rel")).split()}
            if "import" in rel:
                tag.decompose()
                changed = True
                continue

        if tag_name == "meta":
            charset = _compact_scheme_text(_attribute_text(tag.get("charset")))
            http_equiv = _compact_scheme_text(_attribute_text(tag.get("http-equiv")))
            content = _attribute_text(tag.get("content"))
            if charset == "utf-7" or (
                http_equiv == "content-type" and "charset=utf-7" in _compact_scheme_text(content)
            ):
                tag.decompose()
                changed = True
                continue
            if http_equiv == "refresh" and _meta_refresh_is_dangerous(content):
                tag.decompose()
                changed = True
                continue

        # A style block is retained unless it contains executable CSS.  Without
        # a full CSS parser, dropping that one block is safer than attempting a
        # lossy rewrite of otherwise unrelated HTML.
        if tag_name == "style" and _css_is_dangerous(tag.get_text()):
            tag.decompose()
            changed = True
            continue

        remove_animation = False
        animation_target = _local_name(_attribute_text(tag.get("attributeName")))
        if tag_name in _ANIMATION_TAGS and (
            animation_target.startswith("on") or animation_target in _ANIMATED_URL_ATTRIBUTES
        ):
            candidates = [
                _attribute_text(tag.get(name))
                for name in ("from", "to", "by", "values")
                if tag.has_attr(name)
            ]
            if animation_target.startswith("on"):
                remove_animation = True
            elif animation_target == "style":
                remove_animation = any(_css_is_dangerous(value) for value in candidates)
            else:
                remove_animation = any(
                    _is_dangerous_url(part.strip(), allow_raster_data=True)
                    or _css_is_dangerous(part)
                    for value in candidates
                    for part in value.split(";")
                )
        if remove_animation:
            tag.decompose()
            changed = True
            continue

        for attribute_name, raw_value in list(tag.attrs.items()):
            full_name = str(attribute_name).lower()
            local_name = _local_name(attribute_name)
            value = _attribute_text(raw_value)

            # Event-handler attributes include onload, SVG namespaced forms,
            # and malformed variants beginning with an event-handler name.
            if local_name.startswith("on"):
                del tag.attrs[attribute_name]
                changed = True
                continue

            if local_name == "srcdoc":
                if depth >= 8:
                    del tag.attrs[attribute_name]
                    changed = True
                    continue
                sanitized, nested_changed = sanitize_markup(value, depth=depth + 1)
                if nested_changed:
                    tag.attrs[attribute_name] = sanitized
                    changed = True
                continue

            if local_name == "style":
                sanitized_css, css_changed = _sanitize_style_attribute(value)
                if css_changed:
                    if sanitized_css.strip():
                        tag.attrs[attribute_name] = sanitized_css
                    else:
                        del tag.attrs[attribute_name]
                    changed = True
                continue

            is_image_source = tag_name in {
                "image",
                "img",
                "input",
                "source",
                "track",
                "video",
            } and local_name in {"href", "src", "xlink:href"}

            if full_name in _URL_ATTRIBUTES or local_name in _URL_ATTRIBUTES:
                if _is_dangerous_url(value, allow_raster_data=is_image_source):
                    del tag.attrs[attribute_name]
                    changed = True
                continue

            if local_name in _MULTI_URL_ATTRIBUTES:
                if any(_is_dangerous_url(item) for item in value.split()):
                    del tag.attrs[attribute_name]
                    changed = True
                continue

            if local_name in _SRCSET_ATTRIBUTES:
                if _srcset_is_dangerous(value):
                    del tag.attrs[attribute_name]
                    changed = True
                continue

            if local_name in _CSS_VALUE_ATTRIBUTES and _css_is_dangerous(value):
                del tag.attrs[attribute_name]
                changed = True

    if not changed:
        return markup, False
    return soup.decode(formatter=_FORMATTER), True


def sanitize_markup(markup: str, *, depth: int = 0) -> tuple[str, bool]:
    """Sanitize markup and repeat once serialized to prevent mutation XSS."""

    current = markup
    changed_at_all = False
    for _ in range(5):
        sanitized, changed = _sanitize_once(current, depth=depth)
        if not changed:
            return current, changed_at_all
        current = sanitized
        changed_at_all = True
    raise ValueError("HTML did not converge to a safe representation")


def _decode_file(data: bytes) -> tuple[str, str, bytes]:
    bom = b""
    for marker in (
        codecs.BOM_UTF32_BE,
        codecs.BOM_UTF32_LE,
        codecs.BOM_UTF8,
        codecs.BOM_UTF16_BE,
        codecs.BOM_UTF16_LE,
    ):
        if data.startswith(marker):
            bom = marker
            break

    detected = UnicodeDammit(data, is_html=True)
    if detected.unicode_markup is None:
        raise UnicodeError("unable to determine the HTML file encoding")
    encoding = detected.original_encoding or "utf-8"
    return detected.unicode_markup, encoding, bom


def _encode_file(markup: str, encoding: str, bom: bytes) -> bytes:
    try:
        encoded = markup.encode(encoding, errors="xmlcharrefreplace")
    except LookupError:
        encoded = markup.encode("utf-8")
        bom = b""
    if bom and not encoded.startswith(bom):
        encoded = bom + encoded
    return encoded


def filter_file(path: Path) -> bool:
    original = path.read_bytes()
    markup, encoding, bom = _decode_file(original)
    sanitized, changed = sanitize_markup(markup)
    if not changed:
        return False

    output = _encode_file(sanitized, encoding, bom)
    with path.open("wb") as destination:
        destination.write(output)
    return True


def main(argv: list[str]) -> int:
    if len(argv) != 2:
        print(f"Usage: {Path(argv[0]).name} HTML_FILE", file=sys.stderr)
        return 2

    path = Path(argv[1])
    try:
        filter_file(path)
    except (OSError, UnicodeError, ValueError) as error:
        print(f"filter.py: {error}", file=sys.stderr)
        return 1
    return 0


if __name__ == "__main__":
    raise SystemExit(main(sys.argv))

